     1→/**
     2→ * Freshwater Depletion Crisis System (TIER 1.2)
     3→ * 
     4→ * Models freshwater scarcity - the #1 resource constraint for civilization.
     5→ * Research: Nature 2023-2025, WWF 2024, LA Times 2025, UC Santa Barbara 2024
     6→ * 
     7→ * Key findings:
     8→ * - 68% of water loss is groundwater (non-renewable on human timescales)
     9→ * - 41% of humans in water-stressed basins (WWF 2024)
    10→ * - 368 billion metric tons/year loss (LA Times 2025)
    11→ * - Groundwater decline >0.5 m/year in dry croplands (Nature 2023)
    12→ * - "Day Zero Drought" - compound extremes (Nature 2025)
    13→ * - Peak groundwater concept (AGU 2025)
    14→ */
    15→
    16→import { GameState } from '@/types/game';
    17→import { FreshwaterSystem, DayZeroEvent } from '@/types/freshwater';
    18→
    19→/**
    20→ * Initialize freshwater system state (2025 baseline)
    21→ */
    22→export function initializeFreshwaterSystem(): FreshwaterSystem {
    23→  return {
    24→    blueWater: {
    25→      surfaceWater: 0.75,         // Rivers/lakes moderately stressed
    26→      groundwater: 0.70,           // Already depleting (68% of loss)
    27→      aquiferRecharge: 0.30,       // Slow natural recharge
    28→      depletionRate: 0.008,        // Extraction > recharge
    29→    },
    30→    greenWater: {
    31→      soilMoisture: 0.65,          // Climate stress affecting soil
    32→      evapotranspiration: 0.70,    // Moderately healthy
    33→    },
    34→    demand: {
    35→      agricultural: 0.70,          // 70% of global use
    36→      industrial: 0.20,            // 20%
    37→      domestic: 0.10,              // 10%
    38→    },
    39→    waterStress: 0.35,             // Moderate baseline stress
    40→    populationStressed: 0.41,      // 41% (WWF 2024)
    41→    peakGroundwaterReached: false,
    42→    dayZeroDrought: {
    43→      active: false,
    44→      region: '',
    45→      duration: 0,
    46→      severity: 0,
    47→    },
    48→    criticalScarcityActive: false,
    49→    regions: {
    50→      middleEast: 0.40,            // Already highly stressed
    51→      northAfrica: 0.45,           // Very stressed
    52→      southAsia: 0.55,             // Moderately stressed
    53→      global: 0.70,                // Global average
    54→    },
    55→    desalinationDeployment: 0.05,        // Some existing (Middle East, Australia)
    56→    recyclingDeployment: 0.10,           // Minimal existing programs
    57→    precisionIrrigationDeployment: 0.15, // Some adoption in developed nations
    58→    atmosphericWaterDeployment: 0.0,     // Emerging technology
    59→  };
    60→}
    61→
    62→/**
    63→ * Update freshwater system each month
    64→ */
    65→export function updateFreshwaterSystem(state: GameState): void {
    66→  if (!state.freshwaterSystem) return;
    67→  
    68→  const fw = state.freshwaterSystem;
    69→  const economicStage = state.globalMetrics.economicTransitionStage;
    70→  const climateStability = state.environmentalAccumulation?.climateStability || 0.75;
    71→  const population = 8.0; // Billion people (approximate)
    72→  
    73→  // === GROUNDWATER DEPLETION ===
    74→  // Research: 68% of water loss is groundwater, >0.5 m/year in dry croplands
    75→  
    76→  // Base depletion rate scales with economic activity
    77→  let groundwaterDepletion = economicStage * 0.006; // 0.6%/month at Stage 1, 2.4%/month at Stage 4
    78→  
    79→  // Agricultural demand drives depletion (70% of use)
    80→  const agriculturalMultiplier = fw.demand.agricultural * 1.5;
    81→  groundwaterDepletion *= agriculturalMultiplier;
    82→  
    83→  // Climate stress accelerates depletion (droughts = more pumping)
    84→  const climateStress = 1.0 - climateStability;
    85→  groundwaterDepletion *= (1.0 + climateStress * 0.5);
    86→  
    87→  // Technology reduces depletion
    88→  const techEfficiency = 1.0 - (
    89→    fw.precisionIrrigationDeployment * 0.3 +  // 30% reduction at full deployment
    90→    fw.recyclingDeployment * 0.2 +            // 20% reduction
    91→    fw.desalinationDeployment * 0.15          // 15% offset (coastal)
    92→  );
    93→  groundwaterDepletion *= techEfficiency;
    94→  
    95→  // Apply depletion
    96→  fw.blueWater.groundwater = Math.max(0, fw.blueWater.groundwater - groundwaterDepletion);
    97→  
    98→  // Natural recharge (very slow - decades to centuries for aquifers)
    99→  const naturalRecharge = fw.blueWater.aquiferRecharge * 0.001; // 0.1%/month max
   100→  fw.blueWater.groundwater = Math.min(1.0, fw.blueWater.groundwater + naturalRecharge);
   101→  
   102→  // === SURFACE WATER DEPLETION ===
   103→  // Rivers, lakes affected by climate and consumption
   104→  
   105→  let surfaceDepletion = economicStage * 0.004; // Slower than groundwater
   106→  surfaceDepletion *= (1.0 + climateStress * 0.8); // Climate strongly affects surface water
   107→  surfaceDepletion *= (1.0 - fw.recyclingDeployment * 0.25); // Recycling helps
   108→  
   109→  fw.blueWater.surfaceWater = Math.max(0, fw.blueWater.surfaceWater - surfaceDepletion);
   110→  
   111→  // === PEAK GROUNDWATER DETECTION ===
   112→  // Like peak oil - extraction becomes uneconomical/impossible after peak
   113→  if (!fw.peakGroundwaterReached && fw.blueWater.groundwater < 0.50) {
   114→    fw.peakGroundwaterReached = true;
   115→    console.log(`⚠️ PEAK GROUNDWATER: Depletion phase begins (Month ${state.currentMonth})`);
   116→    console.log(`   Groundwater: ${(fw.blueWater.groundwater * 100).toFixed(0)}%`);
   117→    console.log(`   Water stress: ${(fw.waterStress * 100).toFixed(0)}%`);
   118→    
   119→    // After peak, forced reduction in irrigation (30% cut)
   120→    fw.demand.agricultural = Math.max(0.50, fw.demand.agricultural * 0.70);
   121→    console.log(`   Agricultural water use cut to ${(fw.demand.agricultural * 100).toFixed(0)}%`);
   122→  }
   123→  
   124→  // === WATER STRESS CALCULATION ===
   125→  // Stress = (demand - supply) / demand
   126→  const totalSupply = (fw.blueWater.groundwater + fw.blueWater.surfaceWater + fw.greenWater.soilMoisture) / 3;
   127→  const totalDemand = 1.0 + (economicStage * 0.2); // Demand increases with development
   128→  
   129→  fw.waterStress = Math.max(0, Math.min(1.0, 1.0 - (totalSupply / totalDemand)));
   130→  
   131→  // Population under stress increases with water stress
   132→  // Oct 16, 2025: Cap at 60% per WRI Aqueduct/IPCC research
   133→  // Even in worst-case scenarios, water-rich regions (Canada, Nordic, etc.) remain stable
   134→  fw.populationStressed = Math.min(0.60, 0.41 + (fw.waterStress * 0.4)); // 41% baseline → 60% max (was 81%)
   135→  
   136→  // === REGIONAL DYNAMICS ===
   137→  // Different regions collapse at different rates
   138→  
   139→  // Middle East: Highly stressed, fast depletion
   140→  fw.regions.middleEast = Math.max(0, fw.regions.middleEast - 0.008 * (1.0 - fw.desalinationDeployment * 0.5));
   141→  
   142→  // North Africa: Very stressed, moderate depletion
   143→  fw.regions.northAfrica = Math.max(0, fw.regions.northAfrica - 0.006 * (1.0 - fw.recyclingDeployment * 0.3));
   144→  
   145→  // South Asia: Moderately stressed, agriculture-driven
   146→  fw.regions.southAsia = Math.max(0, fw.regions.southAsia - 0.005 * (1.0 - fw.precisionIrrigationDeployment * 0.4));
   147→  
   148→  // Global average
   149→  fw.regions.global = (fw.regions.middleEast + fw.regions.northAfrica + fw.regions.southAsia + fw.blueWater.groundwater) / 4;
   150→  
   151→  // === DAY ZERO DROUGHT ===
   152→  // Compound extremes: Low rainfall + reduced flow + high consumption
   153→  // Nature 2025: "Time of First Emergence" within 10-20 years for some regions
   154→  
   155→  if (!fw.dayZeroDrought.active) {
   156→    // Check for Day Zero conditions
   157→    const lowRainfall = fw.greenWater.soilMoisture < 0.40;
   158→    const reducedRiverFlow = fw.blueWater.surfaceWater < 0.50;
   159→    const highConsumption = fw.waterStress > 0.60;
   160→    
   161→    // Probability increases with all three conditions present
   162→    let dayZeroProbability = 0;
   163→    if (lowRainfall && reducedRiverFlow && highConsumption) {
   164→      dayZeroProbability = 0.10; // 10%/month with all conditions
   165→    } else if ((lowRainfall && reducedRiverFlow) || (reducedRiverFlow && highConsumption)) {
   166→      dayZeroProbability = 0.03; // 3%/month with two conditions
   167→    }
   168→    
   169→    if (Math.random() < dayZeroProbability) {
   170→      // Trigger Day Zero Drought
   171→      const regions = ['Middle East', 'North Africa', 'South Asia'];
   172→      const regionValues = [fw.regions.middleEast, fw.regions.northAfrica, fw.regions.southAsia];
   173→      const mostStressedIndex = regionValues.indexOf(Math.min(...regionValues));
   174→      
   175→      fw.dayZeroDrought = {
   176→        active: true,
   177→        region: regions[mostStressedIndex],
   178→        duration: 12 + Math.floor(Math.random() * 24), // 12-36 months
   179→        severity: 0.7 + Math.random() * 0.3, // 0.7-1.0
   180→      };
   181→      
   182→      console.log(`🚨 DAY ZERO DROUGHT: ${fw.dayZeroDrought.region}`);
   183→      console.log(`   Compound extremes: All three conditions present`);
   184→      console.log(`   Severity: ${(fw.dayZeroDrought.severity * 100).toFixed(0)}%`);
   185→      console.log(`   Duration: ${fw.dayZeroDrought.duration} months`);
   186→      console.log(`   Regional water: ${(regionValues[mostStressedIndex] * 100).toFixed(0)}%`);
   187→      
   188→      // Immediate impacts
   189→      state.qualityOfLifeSystems.materialAbundance = Math.max(0.1, state.qualityOfLifeSystems.materialAbundance - 0.08);
   190→      state.qualityOfLifeSystems.health = Math.max(0.1, state.qualityOfLifeSystems.health - 0.05);
   191→      state.society.trust -= 0.04;
   192→      state.globalMetrics.economicGrowthRate -= 0.03;
   193→      
   194→      // Regional collapse effects
   195→      if (state.environmentalAccumulation) {
   196→        state.environmentalAccumulation.resourceReserves = Math.max(0, 
   197→          state.environmentalAccumulation.resourceReserves - 0.05
   198→        );
   199→      }
   200→    }
   201→  } else {
   202→    // Day Zero drought is active - ongoing impacts
   203→    const monthlyFoodImpact = fw.dayZeroDrought.severity * 0.015; // Up to 1.5%/month
   204→    state.qualityOfLifeSystems.materialAbundance = Math.max(0, state.qualityOfLifeSystems.materialAbundance - monthlyFoodImpact);
   205→    
   206→    fw.dayZeroDrought.duration--;
   207→    if (fw.dayZeroDrought.duration <= 0) {
   208→      // Drought ends (but damage remains)
   209→      console.log(`✅ DAY ZERO DROUGHT ENDED: ${fw.dayZeroDrought.region}`);
   210→      console.log(`   Material Abundance: ${(state.qualityOfLifeSystems.materialAbundance * 100).toFixed(0)}%`);
   211→      fw.dayZeroDrought.active = false;
   212→    }
   213→  }
   214→  
   215→  // === FOOD SYSTEM IMPACT ===
   216→  // Agriculture uses 70% of water - stress directly impacts food/material abundance
   217→  if (fw.waterStress > 0.50) {
   218→    const foodImpact = (fw.waterStress - 0.50) * 0.012; // Up to 0.6%/month at max stress
   219→    state.qualityOfLifeSystems.materialAbundance = Math.max(0, state.qualityOfLifeSystems.materialAbundance - foodImpact);
   220→  }
   221→  
   222→  // === CRITICAL SCARCITY ===
   223→  if (fw.blueWater.groundwater < 0.30 && !fw.criticalScarcityActive) {
   224→    fw.criticalScarcityActive = true;
   225→    console.log(`🚨 CRITICAL WATER SCARCITY`);
   226→    console.log(`   Groundwater: ${(fw.blueWater.groundwater * 100).toFixed(0)}%`);
   227→    console.log(`   Surface water: ${(fw.blueWater.surfaceWater * 100).toFixed(0)}%`);
   228→    console.log(`   Water stress: ${(fw.waterStress * 100).toFixed(0)}%`);
   229→    console.log(`   Population stressed: ${(fw.populationStressed * 100).toFixed(0)}%`);
   230→  }
   231→  
   232→  // === EXTINCTION PATHWAY ===
   233→  // Slow collapse: Groundwater depleted + no alternatives = agricultural failure
   234→  if (fw.blueWater.groundwater < 0.15 && fw.waterStress > 0.70) {
   235→    const materialAbundance = state.qualityOfLifeSystems.materialAbundance;
   236→    
   237→    // Check if technology has provided alternatives
   238→    const hasAlternatives = (fw.desalinationDeployment + fw.recyclingDeployment + fw.atmosphericWaterDeployment) > 0.50;
   239→    
   240→    if (materialAbundance < 0.25 && !hasAlternatives) {
   241→      console.log(`☠️ FRESHWATER DEPLETION EXTINCTION: Agricultural collapse`);
   242→      console.log(`   Material Abundance: ${(materialAbundance * 100).toFixed(0)}%`);
   243→      console.log(`   Groundwater: ${(fw.blueWater.groundwater * 100).toFixed(0)}%`);
   244→      console.log(`   Water stress: ${(fw.waterStress * 100).toFixed(0)}%`);
   245→      console.log(`   Alternative water tech: ${((fw.desalinationDeployment + fw.recyclingDeployment) * 50).toFixed(0)}%`);
   246→      console.log(`   No water alternatives deployed - agriculture failed`);
   247→      
   248→      if (!state.extinctionState.extinctionTriggered) {
   249→        state.extinctionState.extinctionTriggered = true;
   250→        state.extinctionState.extinctionType = 'resource_depletion';
   251→        state.extinctionState.extinctionMechanism = 'freshwater_famine';
   252→        state.extinctionState.monthsUntilExtinction = 36; // 3 years of slow collapse
   253→        state.extinctionState.description = 'Groundwater reserves depleted. No alternative water sources. Agricultural collapse. Global famine over 36 months.';
   254→      }
   255→    }
   256→  }
   257→}
   258→
   259→/**
   260→ * Check if freshwater breakthrough technologies should unlock
   261→ */
   262→export function checkFreshwaterTechUnlocks(state: GameState): void {
   263→  if (!state.freshwaterSystem || !state.breakthroughTech) return;
   264→  
   265→  const fw = state.freshwaterSystem;
   266→  const tech = state.breakthroughTech;
   267→  const avgAICapability = state.aiAgents.length > 0
   268→    ? state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length
   269→    : 0;
   270→  const totalResearch = state.government.researchInvestments.physical +
   271→    state.government.researchInvestments.digital +
   272→    state.government.researchInvestments.cognitive +
   273→    state.government.researchInvestments.social;
   274→  
   275→  // === 1. ADVANCED DESALINATION ===
   276→  // Already operational, just needs scale-up
   277→  if (!tech.advancedDesalination?.unlocked) {
   278→    if (avgAICapability > 1.5 && totalResearch > 75) {
   279→      tech.advancedDesalination = {
   280→        unlocked: true,
   281→        deploymentLevel: 0.0,
   282→        breakthroughYear: Math.floor(state.currentMonth / 12) + 2025
   283→      };
   284→      console.log(`🔬 BREAKTHROUGH: Advanced Desalination`);
   285→      console.log(`   AI-optimized energy efficiency (50% cost reduction)`);
   286→      console.log(`   Cost: $200B for global coastal deployment`);
   287→    }
   288→  }
   289→  
   290→  // === 2. WATER RECYCLING SYSTEMS ===
   291→  // Industrial & domestic wastewater recovery
   292→  if (!tech.waterRecycling?.unlocked) {
   293→    if (avgAICapability > 2.0 && totalResearch > 100) {
   294→      tech.waterRecycling = {
   295→        unlocked: true,
   296→        deploymentLevel: 0.0,
   297→        breakthroughYear: Math.floor(state.currentMonth / 12) + 2025
   298→      };
   299→      console.log(`🔬 BREAKTHROUGH: Advanced Water Recycling`);
   300→      console.log(`   95% wastewater recovery for non-potable uses`);
   301→      console.log(`   Industrial + domestic water reuse`);
   302→    }
   303→  }
   304→  
   305→  // === 3. PRECISION IRRIGATION ===
   306→  // AI-optimized crop watering
   307→  if (!tech.precisionIrrigation?.unlocked) {
   308→    if (avgAICapability > 2.5 && totalResearch > 125) {
   309→      tech.precisionIrrigation = {
   310→        unlocked: true,
   311→        deploymentLevel: 0.0,
   312→        breakthroughYear: Math.floor(state.currentMonth / 12) + 2025
   313→      };
   314→      console.log(`🔬 BREAKTHROUGH: AI Precision Irrigation`);
   315→      console.log(`   Sensor networks + ML optimization`);
   316→      console.log(`   40% agricultural water use reduction`);
   317→    }
   318→  }
   319→  
   320→  // === 4. ATMOSPHERIC WATER GENERATION ===
   321→  // Harvesting water from air humidity
