   334→  
   335→  // === AUTO-DEPLOYMENT ===
   336→  // Simulate market/government adoption
   337→  
   338→  if (tech.advancedDesalination?.unlocked && fw.waterStress > 0.50) {
   339→    // Water scarcity motivates desalination (coastal areas)
