    42→export function updateRefugeeCrises(state: GameState): void {
    43→  const system = state.refugeeCrisisSystem;
    44→
    45→  // === 1. CHECK FOR NEW CRISES ===
    46→  const newCrises = checkRefugeeCrisisTriggers(state);
    47→  system.activeRefugeeCrises.push(...newCrises);
    48→
    49→  // === 2. RESET GLOBAL METRICS ===
    50→  system.totalDisplaced = 0;
    51→  system.globalRefugeeTension = 0;
    52→  system.resettlementCost = 0;
    53→
    54→  // === 3. UPDATE EACH ACTIVE CRISIS ===
    55→  for (const crisis of system.activeRefugeeCrises) {
    56→    if (crisis.resolved) continue;
    57→
    58→    crisis.monthsActive++;
    59→
    60→    // === GRADUAL DISPLACEMENT PHASE (3-5 years) ===
    61→    if (!crisis.displacementComplete && crisis.monthsActive <= crisis.displacementDuration) {
    62→      // 10% of remaining population flees each month
    63→      const fleeingThisMonth = crisis.remainingInSource * crisis.displacementRate;
    64→      crisis.remainingInSource -= fleeingThisMonth;
    65→      crisis.displacedPopulation += fleeingThisMonth;
    66→      crisis.currentlyDisplaced += fleeingThisMonth;
    67→
    68→      // 2% die in transit
    69→      const transitDeaths = fleeingThisMonth * 0.02;
    70→      crisis.deathsInTransit += transitDeaths;
    71→      crisis.currentlyDisplaced -= transitDeaths;
    72→
    73→      // Track transit deaths by category (convert millions to billions)
    74→      const transitDeathsBillions = transitDeaths / 1000;
    75→      const category = crisis.cause === 'war' || crisis.cause === 'nuclear' ? 'war' :
    76→                       crisis.cause === 'famine' ? 'famine' :
    77→                       crisis.cause === 'climate' ? 'climate' :
    78→                       crisis.cause === 'ecosystem' ? 'ecosystem' : 'other';
    79→      state.humanPopulationSystem.deathsByCategory[category] += transitDeathsBillions;
    80→      state.humanPopulationSystem.cumulativeCrisisDeaths += transitDeathsBillions;
    81→
    82→      // Track peak displacement
    83→      crisis.peakDisplacement = Math.max(crisis.peakDisplacement, crisis.currentlyDisplaced);
    84→
    85→      // Mark complete when very few remain (< 1% of original)
    86→      if (crisis.remainingInSource < crisis.potentialDisplaced * 0.01 ||
    87→          crisis.monthsActive >= crisis.displacementDuration) {
    88→        crisis.displacementComplete = true;
    89→        console.log(`📊 DISPLACEMENT COMPLETE: ${crisis.cause} (${crisis.sourceRegion})`);
    90→        console.log(`   Duration: ${crisis.monthsActive} months (${(crisis.monthsActive / 12).toFixed(1)} years)`);
    91→        console.log(`   Total fled: ${crisis.displacedPopulation.toFixed(1)}M`);
    92→        console.log(`   Still in source: ${crisis.remainingInSource.toFixed(1)}M`);
    93→        console.log(`   Deaths in transit: ${crisis.deathsInTransit.toFixed(1)}M`);
    94→      }
    95→    }
    96→
    97→    // === RESETTLEMENT PHASE (ongoing) ===
    98→    // Calculate resettlement rate
    99→    // Base rate: 0.5% of displaced per month (~5 years to resettle 50%)
   100→    const baseRate = crisis.baselineResettlementRate;
   101→    const programBonus = crisis.acceleratedResettlement ? 0.01 : 0;
   102→    const tensionPenalty = crisis.socialTension > 0.7 ? 0.003 : 0;
   103→    const borderPenalty = !system.bordersOpen ? 0.002 : 0;
   104→
   105→    crisis.resettlementRate = Math.max(0.001, baseRate + programBonus - tensionPenalty - borderPenalty);
   106→
   107→    // Apply resettlement
   108→    const resettledThisMonth = crisis.currentlyDisplaced * crisis.resettlementRate;
   109→    crisis.resettledCount += resettledThisMonth;
   110→    crisis.currentlyDisplaced -= resettledThisMonth;
   111→    system.totalResettled += resettledThisMonth;
   112→
   113→    // Update progress
   114→    crisis.resettlementProgress = crisis.resettledCount / crisis.displacedPopulation;
   115→
   116→    // === GENERATIONAL RESETTLEMENT MILESTONE ===
   117→    if (crisis.monthsActive >= crisis.generationLength) {
   118→      // After 1 generation (25 years), remaining refugees are "fully resettled"
   119→      crisis.resettledCount += crisis.currentlyDisplaced;
   120→      crisis.currentlyDisplaced = 0;
   121→      crisis.resolved = true;
   122→      crisis.duration = crisis.monthsActive;
   123→
   124→      // Tension drops sharply
   125→      crisis.socialTension *= 0.3;
   126→      crisis.economicStrain *= 0.2;
   127→
   128→      console.log(`✅ REFUGEE CRISIS RESOLVED: ${crisis.cause} (${crisis.sourceRegion})`);
   129→      console.log(`   Duration: ${crisis.monthsActive} months (${(crisis.monthsActive / 12).toFixed(1)} years)`);
   130→      console.log(`   Total displaced: ${crisis.displacedPopulation.toFixed(1)}M`);
   131→      console.log(`   Resettled: ${crisis.resettledCount.toFixed(1)}M`);
   132→    }
   133→
   134→    // === CALCULATE SOCIAL TENSION ===
   135→    // Tension based on: raw numbers, speed of influx, economic conditions, social stability
   136→    const popRatio = state.humanPopulationSystem.population * 1000; // Convert to millions
   137→    const displacementScale = crisis.currentlyDisplaced / popRatio; // Ratio
   138→    const influxSpeed = crisis.monthsActive < 12 ? 1.5 : 1.0; // Recent = higher tension
   139→    const economicModifier = 1 + (1 - state.globalMetrics.qualityOfLife);
   140→    const stabilityModifier = 1 + (1 - state.globalMetrics.socialStability);
   141→
