   156→    system.resettlementCost += totalCost;
   157→    system.globalRefugeeTension = Math.max(system.globalRefugeeTension, crisis.socialTension);
   158→  }
   159→
   160→  // === 4. CALCULATE TOTAL ECONOMIC STRAIN ===
   161→  system.economicStrain = system.resettlementCost / 1000; // Normalize to 0-1
   162→
   163→  // === 5. APPLY GLOBAL EFFECTS ===
