    socialTension: 0,
    economicStrain: 0,
    politicalInstability: 0,

    // Resolution
    resettlementRate: 0,
    baselineResettlementRate: 0.005, // 0.5% per month
    acceleratedResettlement: false,
    resolved: false,

    // Historical tracking
    peakDisplacement: 0,                          // Will track as people flee
    duration: 0,

    // Severity
    severity,
  };
}

